// sw.js — Service Worker Redoma
const ICON_192 = 'data:image/png;base64,';
const ICON_512 = 'data:image/png;base64,';

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));

// Serve os ícones como arquivos (intercepta /icon-192.png e /icon-512.png)
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  if (url.pathname === '/icon-192.png') {
    event.respondWith(
      fetch(ICON_192).catch(() =>
        fetch('data:image/png;base64,')
      ).catch(() => new Response('', { status: 404 }))
    );
    return;
  }
  if (url.pathname === '/icon-512.png') {
    event.respondWith(
      fetch(ICON_512).catch(() => new Response('', { status: 404 }))
    );
    return;
  }
});

// Recebe mensagem do app para disparar notificação
self.addEventListener('message', (event) => {
  if (event.data?.type === 'NOTIFY') {
    const { title, body, tag } = event.data;
    event.waitUntil(
      self.registration.showNotification(title, {
        body,
        icon: ICON_192,
        badge: ICON_192,
        tag: tag || 'redoma-message',
        renotify: true,
        vibrate: [200, 100, 200],
        data: { url: self.location.origin + '/#/agent/inbox' },
      })
    );
  }
});

// Clique na notificação
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data?.url || self.location.origin + '/#/agent/inbox';
  event.waitUntil(
    self.clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then((clients) => {
        for (const client of clients) {
          if ('focus' in client) {
            client.focus();
            client.navigate(targetUrl);
            return;
          }
        }
        return self.clients.openWindow(targetUrl);
      })
  );
});